def iteration_valeurs(etats, terminaux, actions, transitions, recompense, gamma, seuil):
    V = {}
    for s in etats:
        V[s] = terminaux[s] if s in terminaux else 0.0
    while True:
        delta = 0.0
        W = dict(V)
        for s in etats:
            if s in terminaux:
                continue
            meilleure = None
            for a in actions(s):
                q = sum(p * V[s2] for s2, p in transitions(s, a))
                if meilleure is None or q > meilleure:
                    meilleure = q
            if meilleure is None:
                continue
            W[s] = recompense + gamma * meilleure
            delta = max(delta, abs(W[s] - V[s]))
        V = W
        if delta < seuil:
            break
    politique = {}
    for s in etats:
        if s in terminaux:
            continue
        meilleure, best_a = None, None
        for a in actions(s):
            q = sum(p * V[s2] for s2, p in transitions(s, a))
            if meilleure is None or q > meilleure:
                meilleure, best_a = q, a
        politique[s] = best_a
    return ({s: round(v, 4) for s, v in V.items()}, politique)

def maj(Q, s, a, r, s2, terminal, alpha, gamma):
    futur = 0.0 if terminal else max(Q[s2])
    cible = r + gamma * futur
    Q[s][a] = round(Q[s][a] + alpha * (cible - Q[s][a]), 6)
    return Q[s][a]

def politique(Q):
    res = {}
    for s in Q:
        best = 0
        for k in range(1, len(Q[s])):
            if Q[s][k] > Q[s][best]:
                best = k
        res[s] = best
    return res

from math import log, sqrt

def ucb(stats, c):
    for i, (v, n) in enumerate(stats):
        if n == 0:
            return i
    total = sum(n for _, n in stats)
    meilleur, indice = None, -1
    for i, (v, n) in enumerate(stats):
        score = v / n + c * sqrt(log(total) / n)
        if meilleur is None or score > meilleur:
            meilleur, indice = score, i
    return indice

def coup_final(stats):
    meilleur, indice = -1, -1
    for i, (v, n) in enumerate(stats):
        if n > meilleur:
            meilleur, indice = n, i
    return indice
